def ket(dim, j):
    '''Input:
    dim: int or list, dimension of the ket
    j: int or list, the i-th basis vector
    Output:
    out: dim dimensional array of float, the matrix representation of the ket
    '''
    import numpy as np

    if isinstance(dim, int):
        if isinstance(j, int):
            vector = np.zeros(dim)
            vector[j] = 1
            return vector
        else:
            vectors = [ket(d, i) for d, i in zip(dim, j)]
            return np.kron(*vectors)
    else:
        vectors = [ket(d, j) for d in dim]
        return np.kron(*vectors)
